import{_ as t,c as n,j as e,a as r,o}from"./chunks/framework.CqbvlPrP.js";const f=JSON.parse('{"title":"第二百五十章 无法永远存在","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/250第二百五十章 无法永远存在.md","filePath":"meditation/巴利文大藏经/250第二百五十章 无法永远存在.md"}'),_={name:"meditation/巴利文大藏经/250第二百五十章 无法永远存在.md"};function l(s,a,i,d,c,p){return o(),n("div",null,a[0]||(a[0]=[e("h1",{id:"第二百五十章-无法永远存在",tabindex:"-1"},[r("第二百五十章 无法永远存在 "),e("a",{class:"header-anchor",href:"#第二百五十章-无法永远存在","aria-label":'Permalink to "第二百五十章 无法永远存在"'},"​")],-1),e("p",null,"完全读懂巴利文大藏经",-1),e("p",null,"相应部22相应40经/随法经第二(蕴相应/蕴篇/修多罗)",-1),e("p",null,"有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，佛陀对出家弟子们说：“比丘们（出家人）！你们应该按如来的正法循序渐进的去修行，你们应该这样去观想：「物质事物、物质身体、感受、念想、行为、认识、分别、判断是随时在变化的，是无法永远存在的，是无法永恒保持不变的，是无法永远拥有的。物质事物是会生起、形成、存续、发展、衰败、灭亡、消失的，物质事物随时都在变化；物质身体是会出生、成长、生病、衰老、死亡的，物质身体随时都在变化。感受、念想、行为、认识、分别、判断是会生起、出现、存续、消退、灭尽、消失的，感受、念想、行为、认识、分别、判断随时都在变化。物质事物、物质身体、感受、念想、行为、认识、分别、判断最终给自己带来的是痛苦。」你们经常这样的观想，就能最终从物质事物、物质身体、感受、念想、行为、认识、分别、判断中彻底的解脱出来，就能从忧愁、悲伤、苦闷、忧虑、绝望、出生、衰老、死亡中彻底的解脱出来，你们就能除灭由物质事物、物质身体、感受、念想、行为、认识、分别、判断产生的一切烦恼和痛苦，从生死轮回中永远的解脱出来，你们就能证悟解脱的果位，达到不生不灭的涅槃境界。当你们不再执着和挂念物质事物、物质身体、感受、念想、行为、认识、分别、判断的时候，如来就说你们：「已经永远从烦恼和痛苦中解脱出来。」 ”",-1),e("p",null,"佛陀说法后，听法的出家弟子们都再次的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。",-1)]))}const u=t(_,[["render",l]]);export{f as __pageData,u as default};
